import json, re, sys
path = '/root/container_diff_report.json'
with open(path) as f:
    data = json.load(f)
# Validate missing_containers
missing = data.get('missing_containers')
if not isinstance(missing, list):
    print('missing_containers not a list', file=sys.stderr); sys.exit(1)
if missing != sorted(missing):
    print('missing_containers not sorted', file=sys.stderr); sys.exit(1)
pattern = re.compile(r'^CNT\d{4}$')
for x in missing:
    if not isinstance(x, str) or not pattern.match(x):
        print('invalid ID in missing:', x, file=sys.stderr); sys.exit(1)
# Validate changed_containers
changed = data.get('changed_containers')
if not isinstance(changed, list):
    print('changed_containers not a list', file=sys.stderr); sys.exit(1)
prev = None
for entry in changed:
    if not isinstance(entry, dict):
        print('changed entry not dict', file=sys.stderr); sys.exit(1)
    for k in ['id','field','old_value','new_value']:
        if k not in entry:
            print('missing key', k, 'in entry', entry, file=sys.stderr); sys.exit(1)
    if not pattern.fullmatch(entry['id']):
        print('invalid ID in changed:', entry['id'], file=sys.stderr); sys.exit(1)
    cur = (entry['id'], entry['field'])
    if prev and cur < prev:
        print('changed_containers not sorted', file=sys.stderr); sys.exit(1)
    prev = cur
    # numeric check: if one of old/new is number, both must be numbers
    if isinstance(entry['old_value'], (int, float)) or isinstance(entry['new_value'], (int, float)):
        if not (isinstance(entry['old_value'], (int, float)) and isinstance(entry['new_value'], (int, float))):
            print('numeric field with non-numeric counterpart', entry, file=sys.stderr); sys.exit(1)
print('Validation passed')

